const $=s=>document.querySelector(s);
const safe=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const read=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))||f}catch{return f}};
let products=[],orders=[],category='All supplies',selected;
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4000)}
const cats=['All supplies',...productCategories.map(c=>c[0])];
$('#categories').innerHTML=cats.map((c,i)=>`<button class="${i===0?'active':''}" data-cat="${safe(c)}">${i===0?'▦':productCategories[i-1][1]} &nbsp; ${safe(c)}</button>`).join('');
$('#categories').onclick=e=>{const b=e.target.closest('button');if(!b)return;category=b.dataset.cat;document.querySelectorAll('[data-cat]').forEach(x=>x.classList.toggle('active',x===b));render()};
const unitOf=p=>p.unit||'kg';
function render(){const q=$('#search').value;const list=products.filter(p=>(category==='All supplies'||p.category===category)&&matchesSupply(p,q));const sort=$('#sort').value;list.sort((a,b)=>sort==='price'?a.price-b.price:sort==='delivered'?(a.price+deliveryQuote(a,1).deliveryFee)-(b.price+deliveryQuote(b,1).deliveryFee):sort==='distance'?a.distance-b.distance:b.rating-a.rating);if(sort==='recommended'){const suppliers=new Set();const featured=list.filter(p=>{if(!p.sponsored||p.stock<1||suppliers.has(p.supplier)||suppliers.size>=2)return false;suppliers.add(p.supplier);return true});const featuredIds=new Set(featured.map(p=>p.id));list.splice(0,list.length,...featured,...list.filter(p=>!featuredIds.has(p.id)))}$('#sponsorDisclosure').hidden=!list.some(p=>p.sponsored);$('#resultCount').textContent=`${list.length} listings`;
 $('#cards').innerHTML=list.length?list.map(p=>`<article class="card"><div class="produce ${safe(p.color)}" aria-label="${safe(p.name)}"><span class="badge ${p.sponsored?'sponsored-badge':''}">${p.sponsored?'Sponsored':safe(p.tag)}</span><span aria-hidden="true">${safe(p.emoji)}${safe(p.emoji)}${safe(p.emoji)}</span></div><div class="cardbody"><div class="producttitle"><h3>${safe(p.name)}</h3><span class="price">₹${p.price}<small>/${safe(unitOf(p))}</small></span></div><p class="suppliername">${safe(p.supplier)} · ${safe(p.category)}</p><div class="details"><span>⌖ ${p.distance} km away</span><span><strong>★ ${p.rating}</strong> (${p.reviews})</span></div><p class="delivery-hint">Delivery estimate (1 unit): ₹${deliveryQuote(p,1).deliveryFee}</p><p class="availability">● ${p.stock>0?`${p.stock} ${safe(unitOf(p))} · In stock`:'Currently unavailable'}</p><button class="orderbtn" data-order="${p.id}" ${p.stock<1?'disabled':''}>Compare & order ↗</button></div></article>`).join(''):'<p class="muted">No supplies found. Try another product or category.</p>';
}
$('#search').oninput=render;$('#searchBtn').onclick=render;$('#sort').onchange=render;
$('#cards').onclick=e=>{const b=e.target.closest('[data-order]');if(!b)return;selected=products.find(p=>p.id===+b.dataset.order);$('#dialogTitle').textContent=selected.name;$('#dialogSupplier').textContent=`${selected.supplier} · ₹${selected.price}/${unitOf(selected)} · ${selected.distance} km`;$('#quantityLabel').textContent=`Quantity (${unitOf(selected)})`;$('#qty').max=Math.min(selected.stock,100000);$('#qty').value=Math.min(10,selected.stock);updateTotal();$('#orderDialog').showModal()};
function orderPricing(qty){const subtotal=qty*selected.price,delivery=deliveryQuote(selected,qty,$('#fulfilment').value),deliveryFee=delivery.deliveryFee;return {subtotal,delivery,deliveryFee,total:subtotal+deliveryFee}}
function updateTotal(){const cost=orderPricing(Math.max(0,Number($('#qty').value)||0)),q=cost.delivery;$('#subtotal').textContent='₹'+cost.subtotal.toLocaleString('en-IN');$('#deliveryFee').textContent='₹'+cost.deliveryFee;$('#pickupSaving').hidden=cost.deliveryFee!==0;$('#pickupSaving').textContent=`Pickup savings: ₹${q.deliveryEstimate}`;$('#deliveryCalculation').innerHTML=`<p>Sample supplier distance: ${q.distanceKm} km · Estimated load: ${q.loadKg} kg · ${safe(q.transportType)}</p><div>Base fee <strong>₹${q.baseCost}</strong></div><div>Distance charge <span>${q.distanceKm} km × ₹8/km</span><strong>₹${q.distanceCost}</strong></div><div>Load charge <span>${q.loadKg} kg × ₹2/kg</span><strong>₹${q.loadCost}</strong></div><div>Handling charge <span>${safe(q.transportType)}</span><strong>₹${q.handlingCost}</strong></div><small>Distance and load charges round up to whole rupees.</small>`;$('#total').textContent='₹'+cost.total.toLocaleString('en-IN')}
$('#fulfilment').onchange=updateTotal;$('#qty').oninput=updateTotal;$('#close').onclick=()=>$('#orderDialog').close();
function renderOrders(){$('#orderCount').textContent=orders.length;$('#orderList').innerHTML=orders.length?orders.map(o=>`<article class="orderrow"><div><strong>${safe(o.product)} · ${o.qty} ${safe(unitOf(o))}</strong><p>${safe(o.supplier)} · ${safe(o.fulfilment)}</p><small>Demo #${o.id} · ${safe(o.status)}</small></div><strong>₹${o.total.toLocaleString('en-IN')}</strong>${currentUser?.role==='wholesaler'?'':o.status==='Placed'?`<button data-receive="${o.id}">Mark received</button>`:o.rating?`<span>Reviewed · ${o.rating} ★</span>`:`<label>Rate your order<select data-review="${o.id}"><option value="">Choose rating</option>${[5,4,3,2,1].map(n=>`<option value="${n}">${n} stars</option>`).join('')}</select></label>`}</article>`).join(''):'<p class="muted">Your first restock is a search away. Explore the market to place a demo order.</p>'}
function inventory(){const own=products.filter(p=>currentUser?.role==='wholesaler'&&p.supplier===currentUser.supplier);$('#inventory').innerHTML=own.length?own.map(p=>`<div class="inventoryrow"><div><strong>${safe(p.name)}</strong><p class="muted">${safe(p.category)} · ${safe(unitOf(p))}</p></div><label>Price ₹/${safe(unitOf(p))}<input type="number" min="1" max="10000" value="${p.price}" data-price="${p.id}" aria-label="${safe(p.name)}"></label><label>Available quantity (${safe(unitOf(p))})<input type="number" min="0" max="100000" value="${p.stock}" data-stock="${p.id}" aria-label="${safe(p.name)}"></label><label>Weight per selling unit (kg)<input type="number" min="0.001" max="1000" step="0.001" value="${p.transportWeightKg??transportDefaults(p.category,unitOf(p)).transportWeightKg}" data-weight="${p.id}"></label><label>Handling type<select data-handling="${p.id}">${transportTypes.map(t=>`<option value="${t}" ${(p.transportType||transportDefaults(p.category,unitOf(p)).transportType)===t?'selected':''}>${t}</option>`).join('')}</select></label></div>`).join(''):'<p class="muted">Add your first product to start selling.</p>'}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-page]').forEach(x=>x.classList.toggle('active',x===b));['market','orders','supplier'].forEach(id=>$('#'+id).hidden=id!==b.dataset.page);renderOrders();inventory()});
let recognition;
function searchSpokenSupply(alternatives){const candidates=alternatives.map(normalizeSupplyText).filter(Boolean);const chosen=candidates.find(q=>products.some(p=>matchesSupply(p,q)))||candidates[0]||'';document.querySelector('[data-page="market"]').click();category='All supplies';document.querySelectorAll('[data-cat]').forEach(button=>button.classList.toggle('active',button.dataset.cat==='All supplies'));$('#search').value=chosen;$('#voiceStatus').textContent='Heard: '+chosen;render();$('#cards').scrollIntoView({behavior:'smooth',block:'start'})}
$('#mic').onclick=()=>{const Speech=window.SpeechRecognition||window.webkitSpeechRecognition;if(!Speech){$('#voiceStatus').textContent='Voice recognition is unavailable in this browser. Type your search, or try the example from the sidebar.';return}if(recognition){recognition.stop();return}recognition=new Speech();recognition.lang=$('#language').value;recognition.maxAlternatives=5;recognition.onstart=()=>{$('#voiceStatus').textContent='Listening… say a product name.';$('#mic').style.background='#d6e8bf'};recognition.onresult=e=>{searchSpokenSupply(Array.from(e.results[e.resultIndex||0],result=>result.transcript))};recognition.onerror=e=>{$('#voiceStatus').textContent='Could not use the microphone ('+e.error+'). You can type your search.'};recognition.onend=()=>{recognition=null;$('#mic').style.background=''};recognition.start()};
render();renderOrders();inventory();





